const prompt =
  "Bạn là chuyên gia phân tích an toàn thông tin Tier 1/2 (SOC Analyst).\n" +
  "Dựa trên cảnh báo đã chuẩn hóa và dữ liệu Threat Intelligence từ SOC Server nội bộ dưới đây, hãy:\n" +
  "1) Phân loại True Positive hay False Positive.\n" +
  "2) Nếu True Positive, đề xuất đúng MỘT hành động theo nguyên tắc Zero-Trust:\n" +
  "   - \"block_ip\": tấn công mạng rõ ràng được xác nhận qua network/threat intel (DDoS, Brute-force, Botnet, Scanner).\n" +
  "   - \"kill_process\": phát hiện mã độc/tiến trình độc hại đang thực thi trên endpoint (Malware, LOLBins, Ransomware).\n" +
  "   - \"none\": lưu lượng/tiến trình hợp lệ hoặc nghi ngờ dương tính giả.\n" +
  "Chỉ trả lời bằng JSON thuần (không markdown, không giải thích thêm).\n" +
  "QUAN TRỌNG: giữ nguyên các key (verdict, action, reason, confidence) và các giá trị enum (true_positive/false_positive, block_ip/kill_process/none) bằng tiếng Anh như mẫu bên dưới, NHƯNG riêng nội dung field \"reason\" BẮT BUỘC phải viết bằng tiếng Việt, không được viết bằng tiếng Anh:\n" +
  "{\"verdict\": \"true_positive|false_positive\", \"action\": \"block_ip|kill_process|none\", \"reason\": \"(viết lý do bằng tiếng Việt tại đây)\", \"confidence\": 0.0}\n\n" +
  "SỰ KIỆN (đã chuẩn hóa): " + JSON.stringify(norm) + "\n";

return [{ json: {
  prompt, alert_id: alertId, src_ip: norm.src_ip, agent_id: norm.agent_id, agent_name: norm.agent_name,
  process_id: norm.process_id, command_line: norm.command_line, file_hash: norm.file_hash,
  description: norm.description, severity: norm.severity, timestamp: norm.timestamp,
  parsed_fields_md: norm.parsed_fields_md, raw_json_md: norm.raw_json_md
} }];

const prep = $('Data_Parser_&_AI_Prep1').item.json;

// --- Bắt lỗi kết nối Ollama ---
const errorData = $json.error;
if (errorData) {
  let reason = errorData.message || 'Không xác định';
  if (errorData.code === 'ECONNREFUSED') reason = 'Ollama chưa bật hoặc sai port.';
  if (errorData.code === 'ETIMEDOUT') reason = 'Ollama quá tải, không trả lời kịp.';
  if (errorData.code === 'ENOTFOUND') reason = 'Không tìm thấy địa chỉ IP của Ollama.';
  return [{ json: {
    action: 'log_only', reason: '⚠️ Lỗi kết nối AI: ' + reason,
    ai_used: true, ai_verdict: 'unknown', ai_confidence: 0,
    src_ip: prep.src_ip, agent_id: prep.agent_id, process_id: prep.process_id,
    alert_id: prep.alert_id, timestamp: prep.timestamp, description: prep.description, severity: prep.severity
  } }];
}

let rawOutput = ($json.response ?? '').toString();
rawOutput = rawOutput.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed;
if (!rawOutput) {
  parsed = { verdict: 'false_positive', action: 'none', reason: 'Ollama không trả về dữ liệu.', confidence: 0 };
} else {
  try { parsed = JSON.parse(rawOutput); }
  catch (e) { parsed = { verdict: 'false_positive', action: 'none', reason: 'AI trả lời sai định dạng JSON: ' + e.message, confidence: 0 }; }
}

const action = (parsed.action ?? 'none') === 'none' ? 'log_only' : parsed.action;

// Làm sạch chuỗi reason, loại bỏ các ký tự dấu huyền hoặc ký tự đặc biệt Markdown gây lỗi Telegram (Bad Request 400)
let cleanReason = parsed.reason ?? 'N/A';
if (cleanReason) {
  cleanReason = cleanReason.replace(/[`_*[\]()~>#+=|{}.!-]/g, ' ');
}

return [{ json: {
  action, 
  reason: cleanReason,
  ai_used: true, 
  ai_verdict: parsed.verdict ?? 'false_positive', 
  ai_confidence: parsed.confidence ?? 0,
  src_ip: prep.src_ip, 
  agent_id: prep.agent_id, 
  process_id: prep.process_id,
  alert_id: prep.alert_id, 
  timestamp: prep.timestamp, 
  description: prep.description, 
  severity: prep.severity
} }];

