const items = $('Extract Phishing Payload').all();
const payload = (items && items.length > 0) ? items[0].json : {};
let url = (payload.url || '').trim();

// Nếu URL không có http:// hoặc https:// ở đầu, tự động thêm vào để trích xuất domain an toàn
if (url && !/^https?:\/\//i.test(url)) {
  url = 'http://' + url;
}

const match = url.match(/^https?:\/\/([^\/\s:]+)/i);
const domain = match ? match[1] : null;

if (!domain) {
  throw new Error('Không lấy được domain từ URL. Payload nhận được: ' + JSON.stringify(payload));
}

return [{ json: { 
  ...$json, 
  url: payload.url, 
  employee_ip: payload.employee_ip, 
  timestamp: payload.timestamp, 
  domain 
} }];

const dns = $json;
const prev = $('Extract Domain from URL').item.json;
let ips = [];
if (dns.Answer && dns.Answer.length) {
  // Lọc lấy toàn bộ bản ghi A (type === 1)
  ips = dns.Answer.filter(r => r.type === 1).map(a => a.data);
}
return [{ json: { ...prev, resolved_ips: ips } }];

// Lấy dữ liệu trực tiếp từ node gọi AI model thay vì dùng $json chung chung
const aiModelData = $('Call Phishing Detection Model').first().json;
const extracted = $('Extract Domain from URL').first().json;

const rawProb = aiModelData.phishing_probability ?? 0;

const confidence = rawProb / 100;
const percentText = rawProb;

const reason = `Model AI nội bộ phát hiện URL phishing (xác suất ${percentText}%). Domain: ${extracted.domain}.`;

return [{ json: {
  action: 'block_url',
  ai_used: true,
  ai_verdict: aiModelData.prediction || 'phishing',
  ai_confidence: confidence,
  reason,
  src_ip: (extracted.resolved_ips && extracted.resolved_ips.length > 0) ? extracted.resolved_ips.join(', ') : 'N/A',
  resolved_ips: extracted.resolved_ips || [],
  employee_ip: extracted.employee_ip || extracted.user || 'N/A',
  url: extracted.url || 'N/A',
  domain: extracted.domain || 'N/A',
  agent_id: null,
  process_id: null,
  file_hash: null,
  description: `Phishing URL detected: ${extracted.url}`,
  severity: 'high',
  timestamp: aiModelData.timestamp || new Date().toISOString()
} }];

const d = $('Action Switch1').item.json;
const domain = (d.domain || '').toLowerCase().trim();

if (!domain || !/^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$/.test(domain)) {
  throw new Error('Domain không hợp lệ, từ chối gửi SSH: ' + domain);
}

// const FILE = '/var/db/pfblockerng/dnsbl/SOAR_AutoBlock_custom.txt';
const FILE = '/var/unbound/pfb_dnsbl_SOAR.conf';
const SINKHOLE_IP = '192.168.10.1'; // đổi theo IP sinkhole thực tế 

// Escape để tránh domain chứa ký tự lạ làm gãy lệnh shell (dù regex trên đã chặn hầu hết)
const safeDomain = domain.replace(/"/g, '');

